        { name: 'Grid', color: 'var(--ef-grid)', power: supply ? home * (grid?.incoming ?? 0) / supply : 0 },
        { name: 'Battery', color: 'var(--ef-battery)', power: supply ? home * (battery?.incoming ?? 0) / supply : 0 }
